head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getFormattedHeaderValue]<br/>Header Column 정보를 사용하여 특정 Column 의 포맷을 전달한 값에 적용하여 반환합니다.",
    "validation" : [
        "headerId(필수) 파라미터로 포맷 정보를 가져올 Header Column 의 인덱스를 설정할 수 있어야 합니다.",
        "value(필수) 파라미터로 포맷을 적용할 원본값을 설정할 수 있어야 합니다.",
        "Header Column 에 설정된 displayFormat 또는 displayFormatter 를 value 파라미터 값에 적용하여 반환해야 합니다.",
        "Header Column 에 포맷 속성값이 설정되어 있지 않으면 value 파라미터 값을 그대로 반환해야 합니다.",
        "headerId 파라미터에 해당하는 Header Column 이 존재하지 않으면 undefined 를 반환해야 합니다.",
        "Header Column 에 displayFormat, displayFormatter 가 모두 설정된 경우 displayFormatter 가 적용되어야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 컬럼별 포맷 설정 안내 라벨 생성
    $c.gcm.createLabel('label="col1(인덱스 0): displayFormat ####-##-## 설정 / col2(인덱스 1): displayFormatter 대괄호 설정 / col3(인덱스 2): displayFormat + displayFormatter 모두 설정 / col4(인덱스 3): 포맷 미설정"', '', 'label1');

    // dataList 생성
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성 (Header Column 별 displayFormat / displayFormatter 설정)
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:500px;height:250px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="120" style="" inputType="text" dataType="text" displayFormat="####-##-##" id="hd1" value="col1(format)"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" dataType="text" displayFormatter="function(data){ return \'[\' + data + \']\'; }" id="hd2" value="col2(formatter)"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" dataType="text" displayFormat="####-##-##" displayFormatter="function(data){ return \'(\' + data + \')\'; }" id="hd3" value="col3(both)"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" dataType="text" id="hd4" value="col4(none)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row3">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



scwin.btn_getFormattedHeaderValue_onclick = function () {
    let headerId = Number(par_headerId.getValue());
    let value = par_value.getValue();

    let rtn = target1.getFormattedHeaderValue(headerId, value);

    if (typeof rtn === 'undefined') {
        rtn = 'undefined';
    }

    wf_body_bottom.getObj("scwin").setReturnValue("getFormattedHeaderValue(" + headerId + ", " + value + ") : " + rtn);
}
